def compute(vars):
    high_price = vars["v1"]
    low_price = vars["v2"]
    difference = high_price - low_price

    return {
        "value": difference,
        "trace": {
            "high_price": high_price,
            "low_price": low_price,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "USD per share"
            }
        }
    }
